UPDATE rental_order_delivery SET delivery_status=IF(#{receipt.startAt}<=#{at},'receipt_checking','dispatched'),factory_dispatch_at=#{at},
    receipt_check_start_at=#{receipt.startAt},receipt_check_deadline_at=#{receipt.deadlineAt},updated_at=#{at}
    WHERE rental_order_id=#{receipt.rentalOrderId} AND delivery_status='pending_outbound'
